    while (getline(file, line)) {
        // Split the line into words
        istringstream iss(line);
        string word;
        while (iss >> word) {
            // Increment the word count if the current word matches the given word
            if (word == wordToCount) {
                wordCounts[word]++;
            }
        }
    }

    // Close the file
    file.close();

    // Print the word count
    int totalCount = wordCounts[wordToCount];
    cout << "The word \"" << wordToCount << "\" appears " << totalCount << " times in the file." << endl;

    return 0;
}
```

Dieses Programm verwendet die Standardbibliotheken von C++: 

